<?php
declare(strict_types=1);ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');header('Cache-Control:no-store,private');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);}catch(Throwable $e){exit('اتصال برقرار نیست.');}
$me=ts_require_roles($pdo,['owner','manager']);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('درخواست نامعتبر');}$id=max(0,(int)($_POST['id']??0));$price=max(0,(int)($_POST['price']??0));$stock=max(0,(int)($_POST['stock']??0));if($id){$pdo->prepare('UPDATE products SET price=?,stock=?,updated_at=NOW() WHERE id=? AND active=1')->execute([$price,$stock,$id]);$msg='ذخیره شد.';}}
$q=trim((string)($_GET['q']??''));$f=(string)($_GET['f']??'all');$page=max(1,(int)($_GET['page']??1));$per=80;$where=['active=1'];$pa=[];if($q!==''){$where[]='(name LIKE ? OR barcode LIKE ? OR brand LIKE ?)';$like='%'.$q.'%';array_push($pa,$like,$like,$like);}if($f==='low')$where[]='stock BETWEEN 1 AND 3';elseif($f==='out')$where[]='stock=0';elseif($f==='noprice')$where[]='price=0';elseif($f==='noimage')$where[]="(image_path IS NULL OR image_path='')";elseif($f==='discount')$where[]='original_price IS NOT NULL AND original_price>price';$ws=implode(' AND ',$where);$st=$pdo->prepare('SELECT COUNT(*) FROM products WHERE '.$ws);$st->execute($pa);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$per));if($page>$pages)$page=$pages;$sql='SELECT id,name,barcode,brand,quantity_label,image_path,price,original_price,stock,category FROM products WHERE '.$ws.' ORDER BY stock=0 DESC,stock ASC,id DESC LIMIT '.$per.' OFFSET '.(($page-1)*$per);$st=$pdo->prepare($sql);$st->execute($pa);$rows=$st->fetchAll();$qs=function(int $p)use($q,$f){return '?'.http_build_query(['q'=>$q,'f'=>$f,'page'=>$p]);};
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کاتالوگ کالاها</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1100px;margin:20px auto;padding:0 10px}.filters{display:flex;gap:7px;overflow:auto;margin:10px 0}.filters a{white-space:nowrap;padding:8px 11px;border-radius:999px;background:#fff;border:1px solid #e4ebe5}.filters .on{background:#11823b;color:#fff}.row{display:grid;grid-template-columns:58px 1fr 130px 110px auto;gap:8px;align-items:center;background:#fff;border:1px solid #e6ece7;border-radius:14px;padding:9px;margin:7px 0}.row img{width:52px;height:52px;object-fit:contain}.quick{display:flex;gap:6px}.quick input{width:105px}.pager{display:flex;justify-content:center;gap:8px;margin:18px}.warn{color:#a33;font-weight:800}@media(max-width:750px){.row{grid-template-columns:48px 1fr}.row img{width:44px;height:44px}.quick{grid-column:1/-1}.quick input{flex:1;width:auto}.meta2{display:none}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">📦</span><span><b>کاتالوگ کالاها</b><small>جستجو و ویرایش سریع</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="نام، برند یا بارکد"><input type="hidden" name="f" value="<?=e($f)?>"><button class="btn">جستجو</button></form><div class="filters"><?php foreach(['all'=>'همه','low'=>'رو به اتمام','out'=>'ناموجود','noprice'=>'بدون قیمت','noimage'=>'بدون عکس','discount'=>'تخفیف‌دار'] as $k=>$v):?><a class="<?=$f===$k?'on':''?>" href="?<?=http_build_query(['q'=>$q,'f'=>$k])?>"><?=e($v)?></a><?php endforeach;?></div><p class="muted"><?=number_format($total)?> کالا · صفحه <?=$page?> از <?=$pages?></p><?php foreach($rows as $r):?><div class="row"><?php if($r['image_path']):?><img src="<?=e($r['image_path'])?>" alt=""><?php else:?><div>🛒</div><?php endif;?><div><b><?=e($r['name'])?></b><div class="muted"><?=e(trim(($r['brand']??'').' '.($r['quantity_label']??'')))?> · <code><?=e($r['barcode'])?></code></div><?php if((int)$r['stock']===0):?><span class="warn">ناموجود</span><?php elseif((int)$r['stock']<=3):?><span class="warn">فقط <?=(int)$r['stock']?> عدد</span><?php endif;?></div><div class="meta2"><?=number_format((int)$r['price'])?> تومان</div><div class="meta2">موجودی <?=number_format((int)$r['stock'])?></div><form method="post" class="quick"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="number" min="0" name="price" value="<?=(int)$r['price']?>" title="قیمت"><input type="number" min="0" name="stock" value="<?=(int)$r['stock']?>" title="موجودی"><button class="btn">ذخیره</button><a class="btn pale" href="admin.php?edit=<?=(int)$r['id']?>#add">ویرایش کامل</a></form></div><?php endforeach;?><div class="pager"><?php if($page>1):?><a class="btn pale" href="<?=e($qs($page-1))?>">قبلی</a><?php endif;?><?php if($page<$pages):?><a class="btn" href="<?=e($qs($page+1))?>">بعدی</a><?php endif;?></div></main></body></html>